import random
from datetime import date, timedelta

import pytest

from rfm_lite import score


def make_orders():
    """400 synthetic customers, deterministic via random.Random(2024)."""
    rng = random.Random(2024)
    start = date(2025, 1, 1)
    end = date(2025, 12, 31)
    span = (end - start).days  # inclusive range of offsets
    orders = []
    for cid in range(400):
        n_orders = rng.randint(1, 8)
        for _ in range(n_orders):
            offset = rng.randint(0, span)
            iso = (start + timedelta(days=offset)).isoformat()
            cents = rng.randint(500, 50000)
            orders.append((f"c{cid:04d}", iso, cents))
    return orders


def test_quintile_distribution_within_bounds():
    orders = make_orders()
    result = score(orders, "2025-12-31")
    assert len(result) == 400
    for dim in ("r", "f", "m"):
        counts = {s: 0 for s in range(1, 6)}
        for row in result.values():
            counts[row[dim]] += 1
        for s in range(1, 6):
            assert 60 <= counts[s] <= 100, (
                f"dim={dim} score={s} count={counts[s]} outside [60, 100]"
            )


def test_order_on_asof_gets_recency_five():
    orders = [("lucky", "2025-12-31", 1234)]
    # Add other customers so quintiles exist.
    orders += [
        ("a", "2025-01-01", 100),
        ("b", "2025-06-15", 200),
        ("c", "2025-03-10", 300),
        ("d", "2025-09-01", 400),
    ]
    result = score(orders, "2025-12-31")
    assert result["lucky"]["r"] == 5


def test_single_customer_all_fives():
    result = score([("solo", "2025-05-05", 999)], "2025-12-31")
    assert result["solo"] == {"r": 5, "f": 5, "m": 5, "rfm": "555"}


def test_empty_input_returns_empty_dict():
    assert score([], "2025-12-31") == {}

