"""RFM scoring, stdlib only.

score(orders, asof) -> {customer_id: {"r": int, "f": int, "m": int, "rfm": str}}

Quintiles are computed by sorting values and assigning ceil(5 * rank / n)
with rank 1-based; ties are broken stably by customer_id. Recency is
inverted so the MOST recent customer gets 5.
"""

import math
from datetime import date


def _parse(iso):
    return date.fromisoformat(iso)


def _quintile_scores(items, invert=False):
    """items: list of (customer_id, value).

    Sort ascending by (value, customer_id), assign score = ceil(5*rank/n).
    If invert (recency), return 6 - score so the smallest value
    (most recent) gets 5.
    """
    n = len(items)
    if n == 0:
        return {}
    if n == 1:
        return {items[0][0]: 5}
    ordered = sorted(items, key=lambda kv: (kv[1], kv[0]))
    out = {}
    for rank, (cid, _value) in enumerate(ordered, start=1):
        s = math.ceil(5 * rank / n)
        if invert:
            s = 6 - s
        out[cid] = s
    return out


def score(orders, asof):
    """orders: list[tuple[customer_id, iso_date, amount_cents]].
    asof: ISO date string used as the reference point for recency.
    """
    asof_date = _parse(asof)

    last_order = {}   # cid -> most recent date
    freq = {}         # cid -> order count
    monetary = {}     # cid -> total cents
    for cid, iso_date_str, cents in orders:
        d = _parse(iso_date_str)
        if cid not in last_order or d > last_order[cid]:
            last_order[cid] = d
        freq[cid] = freq.get(cid, 0) + 1
        monetary[cid] = monetary.get(cid, 0) + cents

    recency_items = [(cid, (asof_date - d).days) for cid, d in last_order.items()]
    freq_items = list(freq.items())
    mon_items = list(monetary.items())

    r_scores = _quintile_scores(recency_items, invert=True)
    f_scores = _quintile_scores(freq_items)
    m_scores = _quintile_scores(mon_items)

    return {
        cid: {
            "r": r_scores[cid],
            "f": f_scores[cid],
            "m": m_scores[cid],
            "rfm": f"{r_scores[cid]}{f_scores[cid]}{m_scores[cid]}",
        }
        for cid in last_order
    }

